use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut batch_ids: Vec<String> = Vec::new();
        let mut out = Vec::new();
        for item in items {
            // Duplicate within this batch.
            if batch_ids.iter().any(|i| i == &item.id) {
                continue;
            }
            // Already recorded as seen in the store.
            if state_read::get(&item.id).is_some() {
                continue;
            }
            batch_ids.push(item.id.clone());
            out.push(item);
        }
        out
    }
}

export!(Node);
